import SwiftUI
import UIKit

/// Replica of `FloatingViewportModifier`'s overlay, reduced to the two things
/// issue #114 asks about: which orientation the scene reports, and how much
/// horizontal safe area there is to bleed into.
@main
struct ProbeApp: App {
    var body: some Scene {
        WindowGroup { ProbeView() }
    }
}

private struct Reading {
    var size: CGSize = .zero
    var insets: EdgeInsets = .init()
    var deprecated: UIInterfaceOrientation = .unknown
    var effective: UIInterfaceOrientation = .unknown
    var locked = false
    var resizing = false
    var sceneCount = 0
    var screen: CGSize = .zero
}

private func name(_ o: UIInterfaceOrientation) -> String {
    switch o {
    case .portrait: "portrait"
    case .portraitUpsideDown: "portraitUpsideDown"
    case .landscapeLeft: "landscapeLeft"
    case .landscapeRight: "landscapeRight"
    default: "unknown"
    }
}

/// The switch under test, copied verbatim from `dockBleed(in:)`.
private func bleed(_ o: UIInterfaceOrientation, _ insets: EdgeInsets) -> String {
    switch o {
    case .landscapeLeft: "leading \(Int(insets.leading))"
    case .landscapeRight: "trailing \(Int(insets.trailing))"
    default: "none"
    }
}

private struct ProbeView: View {
    @State private var reading = Reading()

    var body: some View {
        TabView {
            Color.black.tabItem { Label("One", systemImage: "1.circle") }
