            Text("effective   \(name(r.effective))")
                .foregroundStyle(.green)
            Text("locked \(r.locked ? "Y" : "N")  resizing \(r.resizing ? "Y" : "N")")
            Text("bleed(dep) \(bleed(r.deprecated, r.insets))")
